/* ─── INLINE COMPONENTS ─── */

function Breadcrumb() {
  return (
    <div className="ds-breadcrumb">
      <a href="/x_2145749_qc_exec_dashboard.do" className="ds-breadcrumb__link">Executive</a>
      <span className="ds-breadcrumb__sep">&gt;</span>
      <span className="ds-breadcrumb__current">Kolkata / DS-1462</span>
    </div>
  );
}

function StoreHeader() {
  return (
    <div className="ds-store-header">
      <div className="ds-store-header__left">
        <div className="ds-store-header__title-row">
          <h1 className="ds-store-header__title">Kolkata Central DS</h1>
          <span className="ds-store-header__badge">DS-1462</span>
        </div>
        <p className="ds-store-header__subtitle">
          Kolkata · Manager: S. Deshpande · 14 pickers on shift · 6 riders assigned
        </p>
        <div className="ds-store-header__tags">
          <span className="ds-store-header__tag ds-store-header__tag--red">SLA 61.9%</span>
          <span className="ds-store-header__tag ds-store-header__tag--red">Refunds 10%</span>
          <span className="ds-store-header__tag ds-store-header__tag--dark">Avg resolution 129m</span>
        </div>
      </div>
      <div className="ds-store-header__right">
        <span className="ds-store-header__live">
          Updated 11s ago · <span className="ds-store-header__live-dot" /> LIVE
        </span>
      </div>
    </div>
  );
}

function PulseScoreBreakdown() {
  const remaining = 31;
  const total = 100;
  return (
    <div className="ds-pulse-breakdown">
      <div className="ds-pulse-breakdown__equation">
        <span className="ds-pulse-breakdown__eq-item">100 baseline</span>
        {pulseDeductions.map((d) => (
          <span key={d.label} className="ds-pulse-breakdown__eq-item" style={{ color: d.color }}>
            −{d.value} {d.label}
          </span>
        ))}
        <span className="ds-pulse-breakdown__eq-item ds-pulse-breakdown__eq-result">
          = <strong>{remaining}</strong> / 100 PulseScore
        </span>
      </div>
      <div className="ds-pulse-breakdown__bar">
        <div className="ds-pulse-breakdown__segment ds-pulse-breakdown__segment--score" style={{ width: `${(remaining / total) * 100}%` }} />
        {pulseDeductions.map((d) => (
          <div
            key={d.label}
            className="ds-pulse-breakdown__segment"
            style={{ width: `${(d.value / total) * 100}%`, backgroundColor: d.color }}
          />
        ))}
      </div>
      <div className="ds-pulse-breakdown__labels">
        {pulseDeductions.map((d, i) => (
          <span key={d.label} className="ds-pulse-breakdown__label" style={{ color: d.color }}>
            {d.label} −{d.value}{i < pulseDeductions.length - 1 ? ' | ' : ''}
          </span>
        ))}
      </div>
      <p className="ds-pulse-breakdown__footer">
        PulseScore is not a black box: it starts at 100 and subtracts equipment downtime, SLA misses, refund rate and delivery/picker delays. Fix a driver and the score moves.
      </p>
    </div>
  );
}

function KpiCards() {
  return (
    <div className="ds-kpi-row">
      {kpiCards.map((kpi) => (
        <div key={kpi.label} className="ds-kpi-card">
          <span className="ds-kpi-card__label">{kpi.label}</span>
          <div className="ds-kpi-card__value-row">
            <span className="ds-kpi-card__value" style={{ color: kpi.color }}>{kpi.value}</span>
            <span className="ds-kpi-card__unit">{kpi.unit}</span>
          </div>
          <span className="ds-kpi-card__sub">{kpi.sub}</span>
        </div>
      ))}
    </div>
  );
}

function EquipmentChart() {
  const maxVal = 8;
  const labelDates = ['18 Jul', '21 Jul', '24 Jul', '27 Jul', '30 Jul'];
  return (
    <div className="ds-chart-card">
      <h3 className="ds-chart-card__title">Equipment failures — 14 days</h3>
      <p className="ds-chart-card__subtitle">Failures and downtime hours; cold chain drives quality complaints.</p>
      <div className="ds-bar-chart">
        <div className="ds-bar-chart__y-axis">
          {[8, 6, 4, 2, 0].map((v) => (
            <span key={v} className="ds-bar-chart__y-label">{v}</span>
          ))}
        </div>
        <div className="ds-bar-chart__body">
          <div className="ds-bar-chart__grid">
            {[8, 6, 4, 2, 0].map((v) => (
              <div key={v} className="ds-bar-chart__grid-line" />
            ))}
          </div>
          <div className="ds-bar-chart__bars">
            {equipmentData.map((d, i) => (
              <div key={i} className="ds-bar-chart__bar-group">
                <div className="ds-bar-chart__bar ds-bar-chart__bar--failure" style={{ height: `${(d.failures / maxVal) * 100}%` }} />
                <div className="ds-bar-chart__bar ds-bar-chart__bar--downtime" style={{ height: `${(d.downtime / maxVal) * 100}%` }} />
              </div>
            ))}
          </div>
          <div className="ds-bar-chart__x-axis">
            {equipmentData.map((d, i) => (
              <span key={i} className="ds-bar-chart__x-label">
                {labelDates.includes(d.date) ? d.date : ''}
              </span>
            ))}
          </div>
        </div>
      </div>
      <div className="ds-chart-card__legend">
        <span className="ds-chart-card__legend-item"><span className="ds-chart-card__legend-dot" style={{ backgroundColor: '#ef4444' }} /> Failures</span>
        <span className="ds-chart-card__legend-item"><span className="ds-chart-card__legend-dot" style={{ backgroundColor: '#f59e0b' }} /> Downtime hours</span>
      </div>
    </div>
  );
}

function InventoryChart() {
  const maxVal = 20;
  const svgW = 520;
  const svgH = 180;
  const padX = 10;
  const padY = 10;
  const usableW = svgW - padX * 2;
  const usableH = svgH - padY * 2;

  const toX = (i: number) => padX + (i / (inventoryData.length - 1)) * usableW;
  const toY = (v: number) => padY + usableH - (v / maxVal) * usableH;

  const stockoutPoints = inventoryData.map((d, i) => `${toX(i)},${toY(d.stockouts)}`).join(' ');
  const mismatchPoints = inventoryData.map((d, i) => `${toX(i)},${toY(d.mismatches)}`).join(' ');

  const labelDates = ['18 Jul', '21 Jul', '24 Jul', '27 Jul', '30 Jul'];
  const labelIndices = [0, 3, 6, 9, 12];

  // Tooltip for 24 Jul (index 6)
  const tipIdx = 6;
  const tipX = toX(tipIdx);
  const tipY = toY(inventoryData[tipIdx].mismatches);

  return (
    <div className="ds-chart-card">
      <h3 className="ds-chart-card__title">Inventory issues — 14 days</h3>
      <p className="ds-chart-card__subtitle">Stockouts cause substitutions; mismatches cause missing-item claims.</p>
      <div className="ds-line-chart">
        <div className="ds-line-chart__y-axis">
          {[20, 15, 10, 5, 0].map((v) => (
            <span key={v} className="ds-line-chart__y-label">{v}</span>
          ))}
        </div>
        <div className="ds-line-chart__body">
          <svg viewBox={`0 0 ${svgW} ${svgH}`} preserveAspectRatio="none" className="ds-line-chart__svg">
            {/* Grid lines */}
            {[0, 5, 10, 15, 20].map((v) => (
              <line key={v} x1={padX} y1={toY(v)} x2={svgW - padX} y2={toY(v)} stroke="#1e2a45" strokeWidth="1" />
            ))}
            {/* Stockouts line */}
            <polyline points={stockoutPoints} fill="none" stroke="#3b82f6" strokeWidth="2.5" strokeLinejoin="round" />
            {/* Mismatches line */}
            <polyline points={mismatchPoints} fill="none" stroke="#f59e0b" strokeWidth="2.5" strokeLinejoin="round" />
            {/* Tooltip dot */}
            <circle cx={tipX} cy={toY(inventoryData[tipIdx].stockouts)} r="4" fill="#3b82f6" />
            <circle cx={tipX} cy={tipY} r="4" fill="#f59e0b" />
            {/* Vertical line at tooltip */}
            <line x1={tipX} y1={padY} x2={tipX} y2={svgH - padY} stroke="#94a3b8" strokeWidth="0.5" strokeDasharray="3 3" />
          </svg>
          {/* Tooltip box */}
          <div className="ds-line-chart__tooltip" style={{ left: `${(tipIdx / (inventoryData.length - 1)) * 100}%` }}>
            <div className="ds-line-chart__tooltip-box">
              <strong>24 Jul</strong><br />
              Stockouts: 7<br />
              Stock mismatches: 10
            </div>
          </div>
          <div className="ds-line-chart__x-axis">
            {inventoryData.map((d, i) => (
              <span key={i} className="ds-line-chart__x-label">
                {labelIndices.includes(i) ? labelDates[labelIndices.indexOf(i)] : ''}
              </span>
            ))}
          </div>
        </div>
      </div>
      <div className="ds-chart-card__legend">
        <span className="ds-chart-card__legend-item"><span className="ds-chart-card__legend-dot" style={{ backgroundColor: '#3b82f6' }} /> Stockouts</span>
        <span className="ds-chart-card__legend-item"><span className="ds-chart-card__legend-dot" style={{ backgroundColor: '#f59e0b' }} /> Stock mismatches</span>
      </div>
    </div>
  );
}

function WorkOrdersPanel() {
  return (
    <div className="ds-panel">
      <h3 className="ds-panel__title">Open work orders</h3>
      <p className="ds-panel__subtitle">4 open · click a work order to open the field service record and complete the repair.</p>
      <div className="ds-panel__list">
        {workOrders.map((wo) => (
          <div key={wo.id} className="ds-wo-item">
            <div className="ds-wo-item__icon"><WrenchIcon /></div>
            <div className="ds-wo-item__content">
              <div className="ds-wo-item__header">
                <span className="ds-wo-item__id">{wo.id}</span>
                <span className="ds-wo-item__priority" style={{ backgroundColor: wo.pColor }}>{wo.priority}</span>
                <span className="ds-wo-item__status">{wo.status}</span>
              </div>
              <span className="ds-wo-item__asset">{wo.asset}</span>
              <span className="ds-wo-item__sla">{wo.sla}</span>
            </div>
            <div className="ds-wo-item__chevron"><ChevronRight /></div>
          </div>
        ))}
      </div>
    </div>
  );
}

function PendingRepairsPanel() {
  return (
    <div className="ds-panel">
      <h3 className="ds-panel__title">Pending repairs</h3>
      <p className="ds-panel__subtitle">Assets waiting on a technician.</p>
      <div className="ds-panel__list">
        {pendingRepairs.map((r) => (
          <div key={r.asset} className="ds-repair-item">
            <div className="ds-repair-item__info">
              <span className="ds-repair-item__asset">{r.asset}</span>
              <span className="ds-repair-item__name">{r.name}</span>
            </div>
            <span className="ds-repair-item__wait">{r.wait}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

function ComplaintsPanel() {
  return (
    <div className="ds-panel">
      <h3 className="ds-panel__title">Today's complaints</h3>
      <p className="ds-panel__subtitle">Store-attributed, live.</p>
      <div className="ds-panel__list">
        {complaints.map((c) => (
          <div key={c.id} className="ds-complaint-item">
            <div className="ds-complaint-item__icon"><AlertIcon /></div>
            <div className="ds-complaint-item__content">
              <span className="ds-complaint-item__id">{c.id}</span>
              <span className="ds-complaint-item__text">{c.text}</span>
            </div>
            <span className="ds-complaint-item__status" style={{ backgroundColor: `${c.sColor}22`, color: c.sColor, borderColor: c.sColor }}>
              {c.status}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

function TopComplaintCategories() {
  const maxCount = complaintCategories[0].count;
  return (
    <div className="ds-panel">
      <h3 className="ds-panel__title">Top complaint categories</h3>
      <p className="ds-panel__subtitle">Last 7 days at this store.</p>
      <div className="ds-categories__list">
        {complaintCategories.map((cat) => (
          <div key={cat.label} className="ds-category-item">
            <div className="ds-category-item__header">
              <span className="ds-category-item__label">{cat.label}</span>
              <span className="ds-category-item__count">{cat.count}</span>
            </div>
            <div className="ds-category-item__bar-bg">
              <div
                className="ds-category-item__bar-fill"
                style={{ width: `${(cat.count / maxCount) * 100}%`, backgroundColor: cat.color }}
              />
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

/* ─── MAIN COMPONENT ─── */
export default function DarkStoreApp() {
  useEffect(() => {
    document.title = 'Dark Store Dashboard — DS-1462';
  }, []);

  return (
    <div className="ds-app">
      <NavHeader />
      <div className="ds-content">
        <Breadcrumb />
        <StoreHeader />
        <PulseScoreBreakdown />
        <KpiCards />
        <div className="ds-row ds-row--2col">
          <EquipmentChart />
          <InventoryChart />
        </div>
        <div className="ds-row ds-row--3col">
          <WorkOrdersPanel />
          <PendingRepairsPanel />
          <ComplaintsPanel />
        </div>
        <div className="ds-row ds-row--1col">
          <TopComplaintCategories />
        </div>
      </div>
    </div>
  );
}
